<body>
<script type="module">
import * as THREE from 'three';

const scene = new THREE.Scene();
scene.background = new THREE.Color('#ffffff');

const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(244,240);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.03;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const ref = new THREE.OrthographicCamera(-1.6775,1.6775,1.65,-1.65,0.1,30);
ref.name = 'reference-camera';
ref.position.set(0,0.13,8);
ref.lookAt(0,0.04,0);

scene.add(new THREE.HemisphereLight(0xfff9e9,0xd8b56d,1.55));
const key = new THREE.DirectionalLight(0xfff4d9,2.7);
key.position.set(-3.5,6,5);
key.castShadow = true;
key.shadow.mapSize.set(1024,1024);
key.shadow.camera.left=-4;
key.shadow.camera.right=4;
key.shadow.camera.top=5;
key.shadow.camera.bottom=-4;
key.shadow.normalBias=.025;
key.shadow.bias=-.0003;
key.shadow.radius=4;
scene.add(key);
const fill = new THREE.DirectionalLight(0xffffff,.72);
fill.position.set(4,2,4);
scene.add(fill);
const back = new THREE.DirectionalLight(0xffedbe,1.1);
back.position.set(1,4,-5);
scene.add(back);

const character = new THREE.Group();
character.name = 'golden-round-bird';
character.position.x = .025;
scene.add(character);

const bodyGroup = new THREE.Group();
bodyGroup.name = 'body';
character.add(bodyGroup);
const head = new THREE.Group();
head.name = 'head';
head.position.y = .82;
character.add(head);

const skin = new THREE.MeshStandardMaterial({
  vertexColors:true,roughness:.87,metalness:0
});
const yellow = new THREE.MeshStandardMaterial({
  color:0xffbd13,roughness:.88,metalness:0
});
const handMaterial = new THREE.MeshStandardMaterial({
  vertexColors:true,roughness:.95,metalness:0
});
const brown = new THREE.MeshStandardMaterial({
  color:0x665020,roughness:.93
});
const brownLight = new THREE.MeshStandardMaterial({
  color:0x806024,roughness:.93
});
const rimMaterial = new THREE.MeshStandardMaterial({
  color:0x9d8a16,roughness:.85
});
const eyeMaterial = new THREE.MeshStandardMaterial({
  color:0x151b08,roughness:.47
});
const glintMaterial = new THREE.MeshStandardMaterial({
  color:0xd4d5a3,roughness:.35
});
const billMaterial = new THREE.MeshStandardMaterial({
  color:0xffbf27,roughness:.9
});

function ellipsoid(parent,name,material,position,scale){
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(1,40,28),material);
  mesh.name = name;
  mesh.position.set(...position);
  mesh.scale.set(...scale);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
}

const profile = [
  [-2.08,0],[-2.04,.38],[-1.94,.70],[-1.78,.99],
  [-1.57,1.115],[-1.30,1.195],[-.99,1.23],[-.67,1.225],
  [-.36,1.18],[-.06,1.09],[.20,.965],[.43,.825],
  [.64,.685],[.82,.585],[1.04,.525],[1.27,.495],
  [1.45,.465],[1.61,.395],[1.74,.285],[1.82,.13],[1.845,0]
];
function radiusAt(y){
  let i=0;
  while(i<profile.length-2 && y>profile[i+1][0]) i++;
  const a=profile[i],b=profile[i+1];
  const h=b[0]-a[0],t=THREE.MathUtils.clamp((y-a[0])/h,0,1);
  const before=profile[Math.max(0,i-1)];
  const after=profile[Math.min(profile.length-1,i+2)];
  const m0=(b[1]-before[1])/(b[0]-before[0]);
  const m1=(after[1]-a[1])/(after[0]-a[0]);
  const t2=t*t,t3=t2*t;
  const r=(2*t3-3*t2+1)*a[1]+(t3-2*t2+t)*h*m0
         +(-2*t3+3*t2)*b[1]+(t3-t2)*h*m1;
  const d=((6*t2-6*t)*a[1]+(3*t2-4*t+1)*h*m0
         +(-6*t2+6*t)*b[1]+(3*t2-2*t)*h*m1)/h;
  return [Math.max(0,r),d];
}
const gold = new THREE.Color('#ffb914');
const headGold = new THREE.Color('#ffdb12');
const bellyColor = new THREE.Color('#ffdaa0');
const tempColor = new THREE.Color();

function skinColor(x,y,front){
  tempColor.copy(gold).lerp(headGold,THREE.MathUtils.smoothstep(y,.40,1.50));
  const q=(x/.90)**2+((y+.98)/1.40)**2;
  const belly=(1-THREE.MathUtils.smoothstep(q,.70,1.26))
    *THREE.MathUtils.smoothstep(front,.30,.91);
  tempColor.lerp(bellyColor,belly*.96);
  return tempColor;
}
function bodySection(y0,y1,rows,offset){
  const positions=[],normals=[],colors=[],indices=[];
  const segments=96;
  for(let j=0;j<=rows;j++){
    const y=THREE.MathUtils.lerp(y0,y1,j/rows);
    const [r,dr]=radiusAt(y);
    for(let i=0;i<=segments;i++){
      const angle=i/segments*Math.PI*2;
      const s=Math.sin(angle),c=Math.cos(angle);
      const x=r*s;
      positions.push(x,y-offset,r*.755*c);
      const n=new THREE.Vector3(s,-dr,c/.755).normalize();
      normals.push(n.x,n.y,n.z);
      const color=skinColor(x,y,c);
      colors.push(color.r,color.g,color.b);
      if(j<rows&&i<segments){
        const a=j*(segments+1)+i,b=a+segments+1;
        indices.push(a,a+1,b,a+1,b+1,b);
      }
    }
  }
  const geometry=new THREE.BufferGeometry();
  geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geometry.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));
  geometry.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
  geometry.setIndex(indices);
  return geometry;
}
const torso = new THREE.Mesh(bodySection(-2.08,.82,110,0),skin);
torso.name='pear-shaped-torso';
torso.castShadow=true;
torso.receiveShadow=true;
bodyGroup.add(torso);
const headMesh = new THREE.Mesh(bodySection(.82,1.845,65,.82),skin);
headMesh.name='rounded-head-and-neck';
headMesh.castShadow=true;
headMesh.receiveShadow=true;
head.add(headMesh);

const eyes = new THREE.Group();
eyes.name='eyes';
head.add(eyes);
function addEye(name,x,y,angle){
  const group=new THREE.Group();
  group.name=name;
  group.position.set(x,y-.82,.294);
  group.rotation.y=angle;
  eyes.add(group);
  ellipsoid(group,'soft-olive-eye-rim',rimMaterial,[0,0,0],[.076,.108,.039]);
  ellipsoid(group,'black-eye',eyeMaterial,[0,.003,.026],[.052,.079,.036]);
  ellipsoid(group,'small-eye-catchlight',glintMaterial,[-.014,.030,.057],[.012,.016,.007]);
}
addEye('left-eye',-.302,1.362,-.44);
addEye('right-eye',.302,1.402,.44);

const mouth = new THREE.Group();
mouth.name='mouth-and-small-bill';
head.add(mouth);
ellipsoid(mouth,'soft-yellow-bill',billMaterial,[0,1.106-.82,.387],[.226,.091,.124]);
ellipsoid(mouth,'lower-bill',billMaterial,[0,1.054-.82,.399],[.178,.037,.089]);
const smilePoints = [
  new THREE.Vector3(-.148,1.075-.82,.462),
  new THREE.Vector3(-.075,1.050-.82,.491),
  new THREE.Vector3(0,1.043-.82,.503),
  new THREE.Vector3(.075,1.052-.82,.490),
  new THREE.Vector3(.146,1.076-.82,.460)
];
const smile = new THREE.Mesh(
  new THREE.TubeGeometry(new THREE.CatmullRomCurve3(smilePoints),28,.0055,6,false),
  new THREE.MeshStandardMaterial({color:0xd89a22,roughness:1})
);
smile.name='gentle-mouth-crease';
mouth.add(smile);

function catmull(a,b,c,d,t){
  return .5*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);
}
function organicForearm(parent,name,points){
  const pos=[],indices=[],color=[];
  const rows=60,sides=40;
  for(let j=0;j<=rows;j++){
    const u=j/rows*(points.length-1);
    const k=Math.min(points.length-2,Math.floor(u));
    const t=u-k;
    const p0=points[Math.max(0,k-1)],p1=points[k];
    const p2=points[k+1],p3=points[Math.min(points.length-1,k+2)];
    const v=p1.map((_,c)=>catmull(p0[c],p1[c],p2[c],p3[c],t));
    const [y,x,z,r0]=v,r=Math.max(0,r0);
    for(let i=0;i<=sides;i++){
      const a=i/sides*Math.PI*2;
      pos.push(x+Math.sin(a)*r,y,z+Math.cos(a)*r*.90);
      const c=new THREE.Color('#ffc015');
      c.lerp(new THREE.Color('#ed9d13'),.10*(1-Math.cos(a)));
      color.push(c.r,c.g,c.b);
      if(j<rows&&i<sides){
        const q=j*(sides+1)+i;
        indices.push(q,q+1,q+sides+1,q+1,q+sides+2,q+sides+1);
      }
    }
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  geo.setAttribute('color',new THREE.Float32BufferAttribute(color,3));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  const mesh=new THREE.Mesh(geo,skin);
  mesh.name=name;
  mesh.castShadow=true;
  mesh.receiveShadow=true;
  parent.add(mesh);
}
const leftArm=new THREE.Group();
leftArm.name='left-arm-raised';
character.add(leftArm);
const leftUpper=new THREE.Group();
leftUpper.name='left-upper-arm';
leftArm.add(leftUpper);
const upperLeft=ellipsoid(leftUpper,'left-shoulder',yellow,[-.69,.13,.14],[.27,.46,.29]);
upperLeft.rotation.z=-.32;
const leftForearm=new THREE.Group();
leftForearm.name='left-forearm';
leftArm.add(leftForearm);
organicForearm(leftForearm,'rounded-left-forearm',[
  [-.51,-.86,.38,0],
  [-.39,-.90,.41,.20],
  [-.17,-.925,.46,.295],
  [.045,-.89,.50,.30],
  [.235,-.81,.55,.225],
  [.34,-.76,.57,.16],
  [.39,-.75,.58,0]
]);

const rightArm=new THREE.Group();
rightArm.name='right-arm-raised';
character.add(rightArm);
const rightUpper=new THREE.Group();
rightUpper.name='right-upper-arm';
rightArm.add(rightUpper);
const upperRight=ellipsoid(rightUpper,'right-shoulder',yellow,[.94,.08,.015],[.265,.43,.27]);
upperRight.rotation.z=.58;
const rightForearm=new THREE.Group();
rightForearm.name='right-forearm';
rightArm.add(rightForearm);
organicForearm(rightForearm,'rounded-right-forearm',[
  [-.40,1.08,.10,0],
  [-.28,1.17,.14,.205],
  [-.065,1.225,.20,.265],
  [.16,1.215,.26,.255],
  [.36,1.18,.31,.185],
  [.47,1.175,.33,.135],
  [.51,1.175,.33,0]
]);

function palmGeometry(){
  const geometry=new THREE.SphereGeometry(1,36,28);
  const p=geometry.attributes.position;
  const colors=[];
  const upper=new THREE.Color('#59451b');
  const lower=new THREE.Color('#9d6b1b');
  for(let i=0;i<p.count;i++){
    const c=lower.clone().lerp(upper,THREE.MathUtils.smoothstep(p.getY(i),-.85,.75));
    colors.push(c.r,c.g,c.b);
  }
  geometry.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
  return geometry;
}
function addHand(parent,name,position,size,tilt){
  const group=new THREE.Group();
  group.name=name;
  group.position.set(...position);
  group.rotation.z=tilt;
  parent.add(group);
  const palm=new THREE.Mesh(palmGeometry(),handMaterial);
  palm.name='rounded-brown-palm';
  palm.scale.set(size,.20,.17);
  palm.castShadow=true;
  palm.receiveShadow=true;
  group.add(palm);
  const fingers=new THREE.Group();
  fingers.name='curled-fingers';
  group.add(fingers);
  for(let i=0;i<3;i++){
    const x=(i-1)*size*.55;
    ellipsoid(fingers,'knuckle-'+(i+1),brown,
      [x,.135+(i===1?.015:0),-.005],
      [size*.43,.085,.137]);
  }
  const thumb=ellipsoid(group,'curled-thumb',brownLight,
    [size*.65,-.065,.10],[size*.46,.107,.092]);
  thumb.rotation.z=-.35;
  return group;
}
addHand(leftForearm,'left-hand',[-.752,.425,.605],.205,.28);
addHand(rightForearm,'right-hand',[1.187,.581,.365],.151,-.30);

const feet=new THREE.Group();
feet.name='feet';
character.add(feet);
const footMaterial=new THREE.MeshStandardMaterial({color:0xe9a725,roughness:.95});
ellipsoid(feet,'left-foot',footMaterial,[-.46,-2.025,.20],[.30,.105,.38]);
ellipsoid(feet,'right-foot',footMaterial,[.46,-2.025,.20],[.30,.105,.38]);

const ground=new THREE.Mesh(
  new THREE.PlaneGeometry(200,200),
  new THREE.MeshStandardMaterial({color:0xffffff,roughness:1})
);
ground.name='white-ground';
ground.rotation.x=-Math.PI/2;
ground.position.y=-2.125;
ground.receiveShadow=true;
scene.add(ground);

function render(t){
  renderer.render(scene,ref);
}
window.nwb={
  scene,
  renderer,
  cameras:{ref},
  characters:[character],
  render,
  ready:true
};
render(0);
</script>
</body>
